def aplana(datos: list) -> list:
    """
    Aplana una lista (o tupla) anidada, devolviendo una lista con todos los elementos
    que no son listas ni tuplas, en el mismo orden.
    """
    resultado = []

    def _flatten(item):
        if isinstance(item, (list, tuple)):
            for sub in item:
                _flatten(sub)
        else:
            resultado.append(item)

    _flatten(datos)
    return resultado

import csv

def parsear_ventas(texto: str) -> list[dict]:
    # Si el texto está vacío, no hay contenido
    if not texto:
        return []

    # Dividir el texto en líneas (soporta \n y \r\n)
    lines = texto.splitlines()

    # Verificar la cabecera
    header_line = lines[0].strip() if lines else ''
    expected_header = "fecha,producto,cantidad,precio"
    if header_line != expected_header:
        raise ValueError("Cabecera incorrecta")

    # Si solo hay la cabecera, no hay datos
    if len(lines) == 1:
        return []

    result: list[dict] = []

    for line in lines[1:]:
        # Ignorar líneas vacías o que solo contengan espacios
        if not line.strip():
            continue

        # Parsear la fila usando csv para manejar comillas
        try:
            row = next(csv.reader([line]))
        except Exception as e:
            raise ValueError(f"Error al parsear fila: {e}")

        # Cada fila debe tener exactamente 4 campos
        if len(row) != 4:
            raise ValueError("Fila con número incorrecto de campos")

        fecha, producto, cantidad_str, precio_str = row

        # Limpiar espacios en blanco
        fecha = fecha.strip()
        producto = producto.strip()

        # Validar cantidad: debe ser un entero no negativo
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero")
        if cantidad < 0:
            raise ValueError("cantidad negativa")

        # Validar precio: debe ser un número
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número")

        result.append({
            "fecha": fecha,
            "producto": producto,
            "cantidad": cantidad,
            "precio": precio
        })

    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Marcar como usada recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad <= 0:
            # No se puede almacenar nada
            return
        if clave in self._datos:
            # Actualizar y marcar como usada recientemente
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Si la caché está llena, descartar la menos usada
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
